<?php
declare(strict_types=1);
require __DIR__.'/../bootstrap.php';
use Ismile\App;use Ismile\Db;use Ismile\BoothPlan;use Ismile\Map40Upgrade;use Ismile\Sponsors;use Ismile\UserError;
if(App::isLive()||!str_starts_with(App::config('db.name'),'ismile_booth_test_map40_'))throw new RuntimeException('Isolated map 40 test database required.');
$passed=0;$check=static function($name,$ok)use(&$passed){if(!$ok)throw new RuntimeException('FAILED: '.$name);$passed++;echo 'PASS: '.$name.PHP_EOL;};
$folder=dirname(App::config('site_root'));$before=json_decode(file_get_contents($folder.'/before-bookings.json'),true);$calls=json_decode(file_get_contents($folder.'/before-calls.json'),true);
$check('Map upgrade preserves all bookings before the explicit move',Db::all('SELECT * FROM sponsor_requests ORDER BY id')===$before);
BoothPlan::assertDatabaseMatches();$check('Exactly 40 unique visible positions',array_map('intval',array_column(Db::all('SELECT display_number FROM sponsor_map_positions ORDER BY display_number'),'display_number'))===range(1,40));
foreach([25,26,27,28] as $id)$check('Visible booth '.BoothPlan::label($id).' is Bronze with the photo size',BoothPlan::positions()[$id]['tier']==='bronze'&&BoothPlan::positions()[$id]['size']==='2 × 2.25 m');
$check('New booth 40 uses new stable ID 45',BoothPlan::label(45)==='40'&&BoothPlan::positions()[45]['size']==='2 × 3 m'&&BoothPlan::positions()[45]['tier']==='silver');
$check('Existing stable ID 40 stays visible booth 35',BoothPlan::label(40)==='35'&&Db::value("SELECT reserved_booth FROM sponsor_requests WHERE ref='SPN26-KEEP4'")==='40');
$check('All tier capacities agree with the new plan',count(BoothPlan::numbers('silver'))===14&&count(BoothPlan::numbers('bronze'))===13&&(int)Db::value("SELECT places FROM sponsor_packages WHERE id='silver'")===14&&(int)Db::value("SELECT places FROM sponsor_packages WHERE id='bronze'")===13);
$backupCount=count(glob(App::storage('map-backups').'/*.json'));$moved=Map40Upgrade::transfer('SPN26-MOVE4');$after=Db::one("SELECT * FROM sponsor_requests WHERE ref='SPN26-MOVE4'");$expected=$before[0];$expected['booth_number']='45';$expected['reserved_booth']='45';$expected['updated_at']=$after['updated_at'];
$check('Move keeps the same booking and every contact/financial field',$moved['moved']&&$after===$expected);
$check('Other booked positions are completely unchanged',Db::one("SELECT * FROM sponsor_requests WHERE ref='SPN26-KEEP4'")===$before[1]);
$check('All call notes and quoted amounts remain unchanged',Db::all('SELECT * FROM sponsor_calls ORDER BY id')===$calls);
$view=Db::one('SELECT * FROM `15_sponsor_map` WHERE `Map position`=40');$check('Reports show the same company at visible booth 40',$view['Company']===$after['company']&&(int)$view['Internal position ID']===45);
$check('Booth 22 is now available',!Db::value("SELECT id FROM sponsor_requests WHERE reserved_booth='25'"));
$check('Public availability moves to new ID without disturbing ID 40',Sponsors::bookedBooths()===[40,45]);
$check('Private backup is saved',count(glob(App::storage('map-backups').'/*.json'))===$backupCount+1);
$check('Move has an audit record',(int)Db::value("SELECT COUNT(*) FROM audit_log WHERE action='sponsor.map_22_to_40'")===1);
$again=Map40Upgrade::transfer('SPN26-MOVE4');$check('Retry does not move, duplicate or rewrite the booking',$again['alreadyApplied']&&Db::one('SELECT * FROM sponsor_requests WHERE id=?',[$after['id']])===$after&&(int)Db::value("SELECT COUNT(*) FROM audit_log WHERE action='sponsor.map_22_to_40'")===1);
$owner=Db::one("SELECT * FROM admin_users WHERE role='owner' LIMIT 1");
$new=Sponsors::createByStaff(['kind'=>'sponsor','package_id'=>'bronze','booth_number'=>'25','company'=>'New Bronze Attendee','contact'=>'New Contact','phone'=>'+9647501112233'],$owner);$check('Freed booth 22 can be booked only with its Bronze package',$new['package_id']==='bronze'&&BoothPlan::label($new['booth_number'])==='22');
$rejected=false;try{Sponsors::createByStaff(['kind'=>'sponsor','package_id'=>'silver','booth_number'=>'45','company'=>'Duplicate','contact'=>'Duplicate Contact','phone'=>'+9647501112233'],$owner);}catch(UserError){$rejected=true;}$check('Moved booth 40 cannot be double booked',$rejected);
$check('Transfer sends no emails',(int)Db::value('SELECT COUNT(*) FROM emails')===0);
Sponsors::cancel((int)$new['id'],'End of isolated map test.',$owner);
echo $passed.' map 40 checks passed.'.PHP_EOL;
